import{uid,parseTime,clock,mins,replay,stateAt,backup,importBackup,validateDB}from'./engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10H3Zm6 10v-7h6v7',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M16 4a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 11h16',chart:'M4 20V10M10 20V4M16 20v-7M22 20V7',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15Z',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',swap:'M3 7h16m-5-5 5 5-5 5M21 17H5m5-5-5 5 5 5',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m4 12 5 5L20 6',close:'m6 6 12 12M18 6 6 18',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Zm-5 9 3 3 7-7',file:'M5 2h9l5 5v15H5Zm9 0v6h5M8 12h8M8 16h8',back:'M20 12H4m6-6-6 6 6 6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"> <path d="${icons[n]||icons.file}"/></svg>`;
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const initials=n=>n.split(/\s+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const avatar=n=>`<span class="initial">${esc(initials(n))}</span>`;
const emptyDB=()=>({version:1,players:[],teams:[],matches:[],demo:false});
let db,storageError='';try{const raw=localStorage.getItem('controlmin.v1');db=raw?validateDB(JSON.parse(raw)):emptyDB();}catch(e){db=emptyDB();storageError='No se ha podido leer la copia local. No sobrescribiremos tus datos hasta que exportes o restaures una copia.';}
let tacticSwaps=[],tacticPositions=null,tacticFormation=null,tacticFirst=null,setupFirst=null;
let view='matches',teamId=db.teams[0]?.id,matchId=null,editingEvent=null,selIn=new Set(),selOut=new Set(),eventType='sub',eventPeriod=0,eventTime='',isHalftime=false,draft=null,search='',playerFilter='',profileId=null;
const currentTeam=()=>db.teams.find(t=>t.id===teamId),currentMatch=()=>db.matches.find(m=>m.id===matchId),player=id=>db.players.find(p=>p.id===id),team=id=>db.teams.find(t=>t.id===id);
const pname=id=>player(id)?.name||'Jugador desconocido';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){if(storageError)throw Error('Los datos locales están protegidos. Exporta o restaura una copia antes de continuar.');try{localStorage.setItem('controlmin.v1',JSON.stringify(db));}catch(e){throw Error('No se ha podido guardar. El almacenamiento puede estar lleno o bloqueado. Exporta una copia antes de cerrar.');}}
function commit(next){const before=db;db=next;try{persist();}catch(e){db=before;throw e;}}
function mutate(fn){const next=structuredClone(db);fn(next);commit(next);}
function head(title,sub,actions='',eyebrow=''){return`<div class="heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function supportBanner(){return `<section class="support-banner no-print" aria-labelledby="support-title"><div class="support-copy"><div class="eyebrow">Hecho por Raúl · Compartido desde rkoud</div><h2 id="support-title">¿Me invitas a una cerveza virtual? <span aria-hidden="true">🍺</span></h2><p>¡Hola! Soy Raúl, la persona detrás de <strong>rkoud</strong>.</p><details><summary>La historia detrás de estas apps</summary><div class="support-story"><p>Creo aplicaciones para solucionar problemas del día a día y las comparto para que cualquiera pueda usarlas. Como <strong>TimeControl</strong>, que nació para controlar los minutos que juegan los niños en el fútbol base… porque entre los cambios, el banquillo y el partido, bastante tenemos como para hacer cuentas de cabeza.</p><p>Voy creando y mejorando estas herramientas con tiempo, ganas y alguna que otra discusión con la inteligencia artificial.</p><p>Si alguna de mis apps te resulta útil, puedes invitarme a una <strong>cerveza virtual</strong>. Me ayudas a seguir dedicándoles tiempo y a crear nuevas aplicaciones para compartir.</p></div></details><p class="support-joke">Las apps son gratis. La cerveza es voluntaria. Y los fallos… esos intento quitarlos antes de la segunda. <span aria-hidden="true">🍻</span></p></div><div class="support-action"><a class="btn support-button" href="https://buymeacoffee.com/raulcote" target="_blank" rel="noopener noreferrer">Invítame a una cerveza <span aria-hidden="true">🍺</span></a><small>A través de Buy Me a Coffee · Se abre en otra pestaña</small></div></section>`;}
function shell(){const active=profileId?'players':view;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-action="nav" data-view="summary"><img src="./icon.svg" alt=""><span><strong>TimeControl</strong><small>por rkoud</small></span></button><nav>${[['summary','home','Resumen'],['roster','users','Plantilla'],['matches','calendar','Partidos'],['players','users','Jugadores'],['reports','chart','Informes']].map(([v,i,n])=>`<button class="nav ${active===v?'active':''}" data-action="nav" data-view="${v}">${icon(i)}${n}</button>`).join('')}</nav><div class="bottom"><button class="nav ${view==='help'?'active':''}" data-action="nav" data-view="help">${icon('help')}Ayuda y guías</button><button class="nav ${view==='settings'?'active':''}" data-action="nav" data-view="settings">${icon('settings')}Datos y copias</button><div class="saved"><span class="dot"></span>Guardado en este dispositivo</div></div></aside><main class="main"><div class="topbar"><span>Tu equipo, cada minuto.</span><div class="top-actions"><span class="switcher-label">Equipo</span><select id="team-select" aria-label="Equipo activo"><option value="">Selecciona un equipo</option>${db.teams.map(t=>`<option value="${t.id}" ${t.id===teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="iconbtn" data-action="new-team" aria-label="Añadir equipo">${icon('plus')}</button><button class="avatar" data-action="nav" data-view="help" aria-label="Ayuda y guías">${icon('help')}</button><button class="avatar mobile-only" data-action="nav" data-view="settings" aria-label="Datos y copias">${icon('settings')}</button></div></div>${db.demo?`<div class="demo-banner"><span>Estás explorando con datos ficticios. Puedes probar todas las funciones.</span><button data-action="clear-demo">Empezar con mis datos</button></div>`:''}${storageError?`<div class="error">${esc(storageError)}</div>`:''}<div id="content"></div>${supportBanner()}<div class="footer"><span>TimeControl · Una herramienta de rkoud</span><span>Datos locales. Sin registro.</span></div></main></div>`;renderContent();}
function renderContent(){const content=$('#content');if(!db.teams.length&&!['help','settings'].includes(view)){content.innerHTML=welcome();return;}
 if(profileId){content.innerHTML=profile();return;}
 const pages={summary:summary,roster:roster,matches:()=>matchId?analysis():matches(),reports:report,players:players,help:help,settings:settings,setup:setup};content.innerHTML=(pages[view]||matches)();}
function welcome(){return`<div class="welcome card"><img src="./icon.svg" alt=""><div class="eyebrow">MENOS CUENTAS. MÁS FÚTBOL.</div><h1>Cada jugador.<br>Cada minuto cuenta.</h1><p>Guarda tu plantilla, registra los cambios y descubre cuánto juega cada uno. En todos tus equipos, desde un mismo lugar.</p><div class="actions">${button(icon('plus')+' Crear mi primer equipo','new-team','primary')}${button('Explorar con datos ficticios','demo')}</div><p class="welcome-note">Tu información permanece en este navegador.<br>Exporta una copia para conservarla o cambiar de dispositivo.</p></div>`;}
function summary(){const ms=db.matches.filter(m=>m.teamId===teamId),done=ms.filter(m=>m.finished);return head('Cada minuto cuenta.',`Un vistazo a ${esc(currentTeam()?.name||'tus equipos')}.`,button(icon('plus')+' Preparar partido','prepare','primary'),'Tu espacio de equipo')+`<div class="metrics">${metric(currentTeam()?.members.length||0,'Jugadores en plantilla','users')}${metric(ms.length,'Partidos guardados','calendar')}${metric(done.length,'Partidos finalizados','check')}${metric(done.reduce((s,m)=>s+mins(replay(m).duration),0)+' min','Tiempo de juego registrado','clock')}</div><div class="grid two"><section class="card"><div class="card-head"><h2>Últimos partidos</h2>${button('Ver todos','nav','quiet','data-view="matches"')}</div>${matchCards(ms.slice().reverse().slice(0,4))}</section><aside><section class="card info-card"><div class="info-icon">${icon('users')}</div><h2>Una ficha. Todos sus equipos.</h2><p>Consulta el historial de cada jugador, con sus minutos acumulados y el detalle de cada partido.</p>${button('Ver jugadores '+icon('arrow'),'nav','','data-view="players"')}</section><section class="card info-card space-top"><h2>Una copia, tranquilidad.</h2><p>Los datos se guardan en este navegador. Descarga una copia al terminar de trabajar.</p>${button(icon('download')+' Exportar datos','export-modal')}</section></aside></div>`;}
function metric(value,label,i){return`<div class="card metric"><div class="row"><strong>${esc(value)}</strong>${icon(i)}</div><small>${esc(label)}</small></div>`;}
function roster(){const t=currentTeam();if(!t)return welcome();const members=t.members.filter(m=>pname(m.playerId).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(a.number)-Number(b.number));return head('Plantilla del equipo','Tus jugadores, listos para cada partido.',button(icon('upload')+' Importar','import')+button(icon('plus')+' Añadir jugador','new-player','primary'),'Equipo / Plantilla')+`<div class="card team-banner"><div class="row"><div class="crest">${esc(initials(t.name))}</div><div><h2>${esc(t.name)}</h2><p>${esc(t.category||'Tu equipo')} · Fútbol ${t.format}</p></div></div>${button(icon('edit')+' Editar equipo','edit-team')}</div><div class="grid two"><section class="card"><div class="card-head"><h2>Jugadores <span class="badge green">${t.members.length}</span></h2><input class="search" id="roster-search" value="${esc(search)}" placeholder="Buscar jugador" aria-label="Buscar jugador"></div><div class="table-wrap"><table><thead><tr><th>Dorsal</th><th>Nombre</th><th>Posición</th><th>Acciones</th></tr></thead><tbody>${members.map(m=>`<tr><td><span class="num-chip">${esc(m.number||'—')}</span></td><td><div class="namecell">${avatar(pname(m.playerId))}<button data-action="profile" data-id="${m.playerId}">${esc(pname(m.playerId))}</button></div></td><td class="muted small">${esc(player(m.playerId)?.position||'Sin especificar')}</td><td><button class="iconbtn" data-action="edit-player" data-id="${m.playerId}" aria-label="Editar ${esc(pname(m.playerId))}">${icon('edit')}</button><button class="iconbtn" data-action="remove-member" data-id="${m.playerId}" aria-label="Quitar de este equipo">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${!members.length?'<div class="empty"><p>Añade jugadores o vincula una ficha existente.</p></div>':''}<div class="note">✓ Cambios guardados automáticamente en este navegador.</div></section><aside><section class="card info-card"><div class="info-icon">${icon('shield')}</div><h2>Tu plantilla se conserva</h2><p>Se reutiliza en todos tus partidos. La convocatoria de cada encuentro no modifica esta lista.</p><hr><h3>¿Quién juega el próximo partido?</h3><p>Elige los convocados y titulares al preparar cada encuentro.</p>${button('Preparar partido '+icon('arrow'),'prepare')}</section><section class="card info-card space-top"><h2>Copia de seguridad</h2><p>Exporta este equipo con sus jugadores y partidos.</p>${button(icon('download')+' Exportar equipo','export-team')}</section></aside></div>`;}
function matches(){return head('Tus partidos','Prepara un encuentro, continúa un análisis o revisa sus minutos.',button(icon('plus')+' Preparar partido','prepare','primary'),'Equipo / Partidos')+matchCards(db.matches.filter(m=>m.teamId===teamId).slice().reverse());}
function matchCards(ms){if(!ms.length)return`<div class="card empty"><h2>El próximo partido empieza aquí.</h2><p>Selecciona tu convocatoria y registra los tiempos de cámara para comenzar.</p>${button('Preparar partido','prepare','primary')}</div>`;return`<div class="match-list">${ms.map(m=>{const d=new Date((m.date||'2026-01-01')+'T12:00:00');return`<article class="card match-card"><div class="datebox">${esc(d.toLocaleDateString('es',{month:'short'}))}<strong>${d.getDate()}</strong></div><div class="details"><h3>${scoreline(m)}</h3><p>${esc(detailLabel(m))} · Fútbol ${m.format} · ${m.periods.length} ${m.periods.length===1?'parte':'partes'} · ${mins(replay(m).duration)} min · ${m.events.length} eventos</p></div><span class="badge ${m.finished?'green':''}">${m.finished?'Finalizado':'En análisis'}</span><div class="actions">${button('Informe','open-report','','data-id="'+m.id+'"')}${button(m.finished?'Revisar':'Continuar '+icon('arrow'),'open-match','primary','data-id="'+m.id+'"')}</div></article>`;}).join('')}</div>`;}
function startDraft(){const t=currentTeam();if(!t)throw Error('Crea un equipo primero.');draft={id:uid(),teamId:t.id,opponent:'',date:new Date().toLocaleDateString('en-CA'),format:t.format,initialFormation:defaultFormation(t.format),initialPositions:[],competition:'league',round:'',venue:'home',score:null,periodCount:2,periods:[{start:'00:00',end:'25:00'},{start:'35:00',end:'60:00'}],roster:t.members.map(m=>({id:m.playerId,name:pname(m.playerId),number:m.number,called:true,starter:false})),events:[],finished:false};view='setup';matchId=null;shell();}
function setup(){if(!draft)return matches();const called=draft.roster.filter(p=>p.called),starters=called.filter(p=>p.starter);return head('Preparar partido','Elige la convocatoria y los titulares sin modificar tu plantilla.',button('Cancelar','nav','quiet','data-view="matches"'),'Nuevo encuentro')+`<form id="setup-form"><div class="card setup-data"><label>Rival<input name="opponent" value="${esc(draft.opponent)}" placeholder="Nombre del rival" required></label>${matchDetailFields(draft)}<label>Formación inicial (sin portero)<input name="initialFormation" value="${esc(draft.initialFormation)}" placeholder="2-3-1 o 4-3-3" required list="formation-presets"><datalist id="formation-presets">${formationPresets[draft.format].map(f=>`<option value="${f}">${formationLabel(f)}</option>`).join('')}</datalist></label><label>Fecha<input name="date" type="date" value="${esc(draft.date)}" required></label><label>Modalidad<select name="format"><option value="7" ${draft.format===7?'selected':''}>Fútbol 7</option><option value="11" ${draft.format===11?'selected':''}>Fútbol 11</option></select></label><label>Duración<select name="periodCount"><option value="2" ${draft.periodCount===2?'selected':''}>Dos partes</option><option value="1" ${draft.periodCount===1?'selected':''}>Una parte · torneo</option></select></label></div><div class="setup-layout"><section class="card"><div class="card-head"><h2>Convocatoria y titulares</h2><div class="actions"><span class="badge green">${called.length} convocados</span><span class="badge ${starters.length===draft.format?'green':'amber'}">${starters.length} de ${draft.format} titulares</span></div></div><div class="table-wrap"><table><thead><tr><th>Convocado</th><th>Jugador</th><th>Dorsal del partido</th><th>Titular</th></tr></thead><tbody>${draft.roster.map(p=>`<tr><td><input type="checkbox" data-draft="called" data-id="${p.id}" ${p.called?'checked':''} aria-label="Convocar a ${esc(p.name)}"></td><td><div class="namecell">${avatar(p.name)}<strong>${esc(p.name)}</strong></div></td><td><input type="text" maxlength="4" style="width:65px" data-draft="number" data-id="${p.id}" value="${esc(p.number)}" aria-label="Dorsal de ${esc(p.name)}"></td><td><input type="checkbox" data-draft="starter" data-id="${p.id}" ${p.starter&&p.called?'checked':''} ${!p.called?'disabled':''} aria-label="Titular ${esc(p.name)}"></td></tr>`).join('')}</tbody></table></div>${setupFormationPitch()}<div class="note">Los no convocados permanecen en la plantilla. Los dorsales de este partido no cambian los del equipo.</div></section><aside><section class="card form-stack"><h2>Tiempos de cámara</h2><p class="hint">Introduce el inicio y fin reales de cada parte, incluido el añadido. Usa minutos:segundos.</p>${draft.periods.slice(0,draft.periodCount).map((p,i)=>`<div class="fields"><label>Inicio ${i+1}.ª${timeInput({id: "setup-start-"+i,name:"start"+i,value:p.start,label:"inicio "+(i+1)+".ª parte"})}</label><label>Fin ${i+1}.ª${timeInput({id: "setup-end-"+i,name:"end"+i,value:p.end,label:"fin "+(i+1)+".ª parte"})}</label></div>`).join('')}<div class="notice">Verás el vídeo en VEO y registrarás aquí los cambios. El descanso no suma minutos.</div><div id="setup-error"></div><button class="btn primary full" type="submit">Comenzar análisis ${icon('arrow')}</button></section></aside></div></form>`;}
function selectedState(m){let t;try{t=parseTime(eventTime||clock(m.periods[eventPeriod]?.start||0));}catch{return{field:[],blocked:[]};}return stateAt(m,eventPeriod,t,editingEvent);}
function analysis(){const m=currentMatch();if(!m){matchId=null;return matches();}const r=replay(m);if(eventPeriod>=m.periods.length)eventPeriod=0;let state;try{state=selectedState(m);}catch(e){state={field:[],blocked:[]};}const field=m.roster.filter(p=>state.field.includes(p.id)),bench=m.roster.filter(p=>!state.field.includes(p.id));
 return head('Análisis del partido',`${scoreline(m)}<br>${esc(detailLabel(m))} · Fútbol ${m.format}`,button(icon('edit')+' Datos del partido','edit-match')+button('Informe '+icon('arrow'),'open-report','','data-id="'+m.id+'"')+button(m.finished?'Reabrir análisis':'Finalizar partido','finish',m.finished?'':'primary'),'Vídeo · tiempos manuales')+`<div class="card times-card"><h3>Tiempos de cámara</h3><div class="time-fields">${m.periods.map((p,i)=>`<div><span class="label">Inicio ${i+1}.ª</span><strong class="small">${clock(p.start)}</strong></div><div><span class="label">Fin ${i+1}.ª</span><strong class="small">${clock(p.end)}</strong></div>`).join('')}</div><div class="timing-summary"><strong>${mins(r.duration)} min</strong><small>Descanso excluido</small></div><button class="iconbtn" data-action="edit-times" aria-label="Editar tiempos de cámara">${icon('edit')}</button></div><div class="row between no-print" style="margin-bottom:16px"><p class="hint">Consulta VEO en otra ventana. Selecciona el tiempo y después quién sale y quién entra.</p>${m.periods.length===2?button('Cambios en el descanso','halftime','quiet'):''}</div>${m.finished?'<div class="notice space-top" style="margin-bottom:18px">Partido finalizado. Reabre el análisis para modificar los eventos.</div>':''}<div class="grid three"><section class="card"><div class="card-head"><h2>En el campo <span class="badge green">${field.length}</span></h2><span class="small muted">En el instante elegido</span></div>${matchPitch(m,state)}</section><section class="card"><div class="card-head"><h2>Banquillo</h2><span class="badge">${bench.length}</span></div><div class="bench">${bench.map(p=>playerCard(p,'in',m.finished||state.blocked.includes(p.id),state.blocked.includes(p.id))).join('')}</div></section><section class="card"><div class="card-head"><h2>${icon('swap')} ${editingEvent?'Editar evento':'Registrar cambio'}</h2></div><div class="event-form ${isTactic()?'tactic-mode':''}"><div class="event-types">${[['sub','Cambio'],['referee','Petición del árbitro'],['formation','Cambio de formación'],['position','Intercambiar posiciones'],['red','Expulsión'],['injury','Lesión sin cambio']].map(([t,l])=>`<button data-action="event-type" data-type="${t}" class="${eventType===t?'active':''}" ${m.finished?'disabled':''}>${l}</button>`).join('')}</div><label>Parte<select id="event-period" ${m.finished?'disabled':''}>${m.periods.map((p,i)=>`<option value="${i}" ${i===eventPeriod?'selected':''}>${i+1}.ª parte</option>`).join('')}</select></label><label>Tiempo de cámara${timeInput({id:"event-time",value:eventTime||clock(m.periods[eventPeriod].start),disabled:m.finished||isHalftime,label:"cámara"})}</label><div class="summary-selection">${isTactic()?tacticControls(m,state):''}${eventType==='referee'?'<p class="hint">Cambio temporal a petición del árbitro. El niño podrá volver a entrar mediante otro cambio; no es una expulsión definitiva.</p>':''}${isHalftime?'<span class="badge green">Cambio en el descanso</span>':''}<div class="selection out">↓ Sale: ${[...selOut].map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')||'selecciona en el campo'}</div>${['sub','referee'].includes(eventType)?`<div class="selection">↑ Entra: ${[...selIn].map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')||'selecciona en el banquillo'}</div>`:'<p class="hint">Salida definitiva. Este jugador no podrá volver a entrar en el partido.</p>'}</div><button class="btn primary full" data-action="save-event" ${m.finished?'disabled':''}>${editingEvent?'Guardar corrección':isTactic()?'Confirmar '+(eventType==='formation'?'formación':'posiciones'):'Confirmar '+(['sub','referee'].includes(eventType)?'cambio':'salida')} ${icon('check')}</button><button class="btn quiet full" data-action="clear-event">${editingEvent?'Cancelar edición':'Limpiar selección'}</button></div></section></div><div class="grid two analysis-bottom"><section class="card"><div class="card-head"><h2>Participación por jugador</h2><span class="badge">Minutos previstos al completar el partido</span></div>${timeline(m,r)}<p class="footnote">Los tramos abiertos llegan al final configurado de cada parte. El informe será definitivo al finalizar el análisis.</p></section><section class="card"><div class="card-head"><h2>Historial de eventos</h2><span class="badge">${r.events.length}</span></div>${eventList(m,r.events)}</section></div>`;
}
function playerCard(p,side,disabled,blocked=false){const selected=(side==='in'?selIn:selOut).has(p.id);return`<button class="player-card ${selected?side:''} ${blocked?'blocked':''}" data-action="select-player" data-id="${p.id}" data-side="${side}" ${disabled?'disabled':''}>${avatar(p.name)}<strong><span class="num">${esc(p.number||'—')}</span>${esc(p.name)}</strong>${selected?`<span class="selected-tag">${side==='in'?'Entra':'Sale'}</span>`:''}${blocked?'<span class="badge red">Baja</span>':''}</button>`;}
function report(){let m=currentMatch();if(!m){const ms=db.matches.filter(m=>m.teamId===teamId);return head('Informes','Selecciona el partido que quieres consultar.','', 'Minutos y participación')+matchCards(ms.slice().reverse());}const r=replay(m),zero=r.rows.filter(p=>!p.total);return`<div class="print-only print-brand">TimeControl · por rkoud.com ${db.demo?' · EJEMPLO FICTICIO':''}</div>`+head(esc(reportName(m,team(m.teamId)?.name)),`${scoreline(m)}<br>${esc(detailLabel(m))} · ${esc(m.date)}`,button(icon('back')+' Volver al partido','open-match','','data-id="'+m.id+'"')+button(icon('download')+' Exportar informe','report-export','primary'),'Informes / Partido')+`<div class="report-meta"><span class="badge ${m.finished?'green':'amber'}">${m.finished?'✓ Partido finalizado':'Informe provisional'}</span><span class="hint">Fútbol ${m.format} · ${m.periods.length} ${m.periods.length===1?'parte':'partes'} · Descanso excluido</span></div><div class="metrics">${metric(mins(r.duration)+' min','Tiempo de juego','clock')}${metric(m.roster.length,'Convocados','users')}${metric(r.rows.length-zero.length,'Con participación','check')}${metric(zero.length,'Sin participación','users')}</div><section class="card report-card"><div class="card-head"><h2>Participación por jugador</h2><span class="badge">Tramos reales · minutos enteros</span></div>${timeline(m,r)}<p class="footnote">Los minutos de cada parte y el total se redondean por separado al minuto más cercano, a partir de los segundos reales. El porcentaje usa la duración real, incluido el añadido. ${!m.finished?'Los tramos abiertos se proyectan hasta el final configurado.':''}</p></section>${zero.length?`<div class="notice warn space-top">Sin participación: ${zero.map(p=>esc(p.name)).join(', ')}.</div>`:''}${tacticalReport(m)}<div class="report-extras space-top"><p class="hint">Total del equipo: ${mins(r.rows.reduce((s,p)=>s+p.total,0))} minutos. Tiempos de cámara: ${m.periods.map((p,i)=>`${i+1}.ª ${clock(p.start)}–${clock(p.end)}`).join(' · ')}.</p></div><div class="print-only space-top">TimeControl · rkoud.com · ${db.demo?'Datos ficticios. ':''}Informe generado desde los datos guardados en este navegador.</div>`;}
function profile(){const p=player(profileId);if(!p){profileId=null;return players();}const ms=db.matches.filter(m=>m.finished&&m.roster.some(r=>r.id===p.id)&&(!playerFilter||m.teamId===playerFilter)),rs=ms.map(m=>({m,row:replay(m).rows.find(r=>r.id===p.id)})),total=rs.reduce((s,r)=>s+r.row.total,0),possible=ms.reduce((s,m)=>s+replay(m).duration,0);return head(esc(p.name),'Una ficha única. Todos sus minutos.',button('Todos los jugadores','nav','','data-view="players"'),'Jugador / Historial')+`<div class="row" style="margin-bottom:22px"><label>Filtrar por equipo <select id="profile-team"><option value="">Todos los equipos</option>${db.teams.map(t=>`<option value="${t.id}" ${t.id===playerFilter?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="metrics">${metric(mins(total)+' min','Minutos acumulados','clock')}${metric(ms.length,'Convocatorias finalizadas','calendar')}${metric(rs.filter(r=>r.row.total).length,'Partidos con participación','check')}${metric((possible?Math.round(total/possible*100):0)+'%','Del tiempo disponible','chart')}</div><section class="card"><div class="card-head"><h2>Historial de partidos</h2></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Equipo / Rival</th><th>Dorsal</th><th>Minutos</th><th>%</th><th></th></tr></thead><tbody>${rs.slice().reverse().map(({m,row})=>`<tr><td>${esc(m.date)}</td><td><strong>${esc(team(m.teamId)?.name)}</strong><br><span class="muted small">vs ${esc(m.opponent)}</span></td><td>${esc(row.number)}</td><td><strong>${mins(row.total)} min</strong></td><td>${row.percent}%</td><td>${button('Informe','open-report','quiet','data-id="'+m.id+'"')}</td></tr>`).join('')}</tbody></table></div>${!rs.length?'<div class="empty"><p>Aún no hay partidos finalizados para este filtro.</p></div>':''}<div class="note">El total se obtiene sumando los segundos de todos los partidos antes de redondear.</div></section>`;}
function help(){return head('Ayuda y guías','Lo necesario para centrarte en el partido.','', 'A tu lado, desde el primer minuto')+`<div class="help-grid"><article class="card"><h2>01 · Prepara tu equipo</h2><p>Crea un equipo y añade su plantilla. Si un jugador ya existe en otro equipo, vincula su ficha en lugar de crear otra. Puede llevar un dorsal distinto en cada equipo y partido.</p></article><article class="card"><h2>02 · Analiza con VEO</h2><ol><li>Abre VEO en otra ventana.</li><li>Configura los tiempos reales de cámara de una o dos partes.</li><li>Introduce el tiempo del evento y selecciona quién sale y quién entra.</li><li>Confirma uno o varios cambios a la vez.</li></ol></article><article class="card"><h2>03 · Descanso y salidas</h2><p>Si no registras cambios en el descanso, continúan los mismos jugadores. Usa «Cambios en el descanso» para sustituirlos al inicio de la segunda parte. Expulsión y lesión sin cambio son salidas definitivas; no permiten regresar. «Petición del árbitro» registra una sustitución temporal: el niño puede volver mediante otro cambio.</p></article><article class="card"><h2>Formación y posiciones</h2><p>Elige la formación inicial al preparar el partido y pulsa dos puestos para intercambiarlos, incluido el portero. Durante el análisis, usa «Cambio de formación» o «Intercambiar posiciones», introduce el tiempo y confirma. El informe guarda el sistema y el momento del cambio. Los jugadores entrantes heredan el puesto del saliente. Los dos puntos del reloj son fijos; después de dos cifras de minutos el cursor pasa a segundos. Para tiempos de más de 99 minutos, activa «100+».</p></article><article class="card"><h2>04 · Corrige e informa</h2><p>Puedes corregir o borrar cualquier evento. El historial se recalcula cronológicamente; si una corrección hace incoherente otro evento, se explica el conflicto antes de guardar. Reabre un partido finalizado para corregirlo.</p></article><article class="card"><h2>05 · Entiende los minutos</h2><p>Se conservan los segundos. Cada parte y el total se redondean de forma independiente al minuto más cercano. El porcentaje se calcula con los segundos reales. Antes de finalizar el análisis, los intervalos abiertos son minutos previstos.</p></article><article class="card"><h2>06 · Conserva tus datos</h2><p>Los datos pertenecen a este navegador y dirección web. No se sincronizan entre dispositivos. Exporta todos los equipos, un equipo o un partido. Al importar se sustituye el ámbito elegido; antes se guarda una copia local de recuperación.</p></article><article class="card"><h2>Vídeos de guía</h2><p>Prepararemos las guías en vídeo cuando el flujo de la aplicación esté validado. Mientras tanto, estas instrucciones están disponibles en cualquier momento.</p></article><article class="card"><h2>PDF y correo</h2><p>Para el móvil, elige «PDF móvil 9:16»: se descarga directamente con portada y páginas adaptadas. También puedes descargar las páginas como imágenes en ZIP o imprimir en A4 vertical. Para enviar una copia por correo, descárgala y adjúntala manualmente. Si tu navegador permite compartir archivos, puedes usar el botón Compartir.</p></article></div>`;}
function settings(){return head('Tus datos, a salvo.','Copias completas o por equipo y partido. Tú decides.','', 'Datos y copias')+`<div class="grid two"><section class="card info-card"><div class="info-icon">${icon('download')}</div><h2>Exportar e importar</h2><p>Descarga un archivo JSON para guardar tus datos o enviarlo por correo. La copia incluye las fichas necesarias para conservar el historial.</p><div class="actions">${button(icon('download')+' Exportar copia','export-modal','primary')}${button(icon('mail')+' Exportar por correo','email-modal')}${button(icon('upload')+' Importar copia','import')}</div><hr><h3>Al importar</h3><p>La copia importada sustituye los datos del ámbito elegido. Los otros equipos o partidos se conservan. Las fichas de jugador compartidas se actualizan con los datos de la copia.</p>${button('Descargar copia previa a la última importación','recovery')}</section><aside><section class="card info-card"><h2>Guardado en este navegador</h2><p>Sin cuentas ni servidor de datos. Borrar el almacenamiento del navegador elimina la información local. Una copia exportada permite recuperarla.</p><p>La fecha de la copia se muestra antes de importarla. Para conservar la última, importa el archivo más reciente.</p></section><section class="card info-card space-top"><h2>Reiniciar aplicación</h2><p>Elimina los datos de este navegador. Exporta antes una copia si quieres conservarlos.</p>${button('Borrar todos los datos','reset','danger')}</section></aside></div>`;}
function modal(title,body,onSubmit){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}</div><div id="modal-error"></div>${onSubmit?'<div class="form-footer"><button type="button" class="btn quiet" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">Guardar</button></div>':''}</form>`;if(!d.open)d.showModal();$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit?.(new FormData(e.target));}catch(e){$('#modal-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};}
function closeModal(){$('#modal').close();}
function confirmAction(title,desc,fn,label='Confirmar'){modal(title,`<p>${desc}</p><div class="form-footer"><button type="button" class="btn quiet" data-action="close-modal">Cancelar</button><button type="button" id="confirm-action" class="btn primary">${esc(label)}</button></div>`);$('#confirm-action').onclick=()=>{try{fn();closeModal();shell();}catch(e){$('#modal-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};}
function teamModal(edit=false){const t=edit?currentTeam():null;modal(edit?'Editar equipo':'Nuevo equipo',`<div class="fields"><label class="field-full">Nombre del equipo<input name="name" value="${esc(t?.name||'')}" required maxlength="80" placeholder="Ej. CD Norte"></label><label>Categoría<input name="category" value="${esc(t?.category||'')}" maxlength="60" placeholder="Ej. Alevín A"></label><label>Modalidad<select name="format"><option value="7" ${t?.format===7?'selected':''}>Fútbol 7</option><option value="11" ${t?.format===11?'selected':''}>Fútbol 11</option></select></label></div>`,fd=>{const name=fd.get('name').trim();if(!name)throw Error('Introduce un nombre.');const id=t?.id||uid();mutate(d=>{if(t)Object.assign(d.teams.find(x=>x.id===id),{name,category:fd.get('category').trim(),format:+fd.get('format')});else d.teams.push({id,name,category:fd.get('category').trim(),format:+fd.get('format'),members:[]});});teamId=id;view='roster';profileId=null;matchId=null;closeModal();shell();toast('Equipo guardado');});}
function playerModal(id){const p=id?player(id):null,t=currentTeam(),member=t.members.find(m=>m.playerId===id),existing=db.players.filter(p=>!t.members.some(m=>m.playerId===p.id));modal(p?'Editar jugador':'Añadir jugador',`<div class="form-stack">${!p&&existing.length?`<label>Vincular una ficha existente<select name="existing" id="existing-player"><option value="">Crear una nueva ficha</option>${existing.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><p class="hint">Si juega en otro equipo, vincula su ficha para sumar todo su historial.</p>`:''}<label>Nombre<input name="name" id="new-player-name" value="${esc(p?.name||'')}" ${p||!existing.length?'required':''} maxlength="80" placeholder="Nombre del jugador"></label><div class="fields"><label>Dorsal en este equipo<input name="number" value="${esc(member?.number||'')}" maxlength="4"></label><label>Posición (opcional)<select name="position">${['','Portero','Defensa','Centrocampista','Delantero'].map(pos=>`<option ${pos===p?.position?'selected':''}>${pos}</option>`).join('')}</select></label></div>${p?'<p class="hint">El nombre y la posición pertenecen a su ficha única. El dorsal cambia solo en este equipo. Los partidos ya creados conservan sus datos históricos.</p>':''}</div>`,fd=>{let pid=p?.id||fd.get('existing')||uid(),name=String(fd.get('name')||'').trim(),position=fd.get('position');const linked=!!fd.get('existing');if(!linked&&!name)throw Error('Introduce el nombre del jugador.');if(!p&&!linked&&db.players.some(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Ya hay una ficha con ese nombre. Vincúlala desde la lista o usa un nombre que permita distinguirlos.');mutate(d=>{if(p)Object.assign(d.players.find(x=>x.id===pid),{name,position});else if(!linked)d.players.push({id:pid,name,position});const members=d.teams.find(x=>x.id===t.id).members;if(p)members.find(m=>m.playerId===pid).number=fd.get('number').trim();else members.push({playerId:pid,number:fd.get('number').trim()});});closeModal();shell();toast('Jugador guardado');});}
function resetEvent(m=currentMatch()){tacticSwaps=[];tacticPositions=null;tacticFormation=null;tacticFirst=null;editingEvent=null;selIn.clear();selOut.clear();eventType='sub';isHalftime=false;eventPeriod=0;eventTime=m?clock(m.periods[0].start):'';}
function editTimes(){const m=currentMatch();modal('Tiempos reales de cámara',`<div class="form-stack"><p class="hint">Incluye el tiempo añadido. Los cambios de descanso se desplazarán al nuevo inicio de la segunda parte; el resto conserva sus tiempos de cámara.</p>${m.periods.map((p,i)=>`<div class="fields"><label>Inicio ${i+1}.ª${timeInput({id:"edit-start-"+i,name:"start"+i,value:clock(p.start),label:"inicio "+(i+1)+".ª parte"})}</label><label>Fin ${i+1}.ª${timeInput({id:"edit-end-"+i,name:"end"+i,value:clock(p.end),label:"fin "+(i+1)+".ª parte"})}</label></div>`).join('')}</div>`,fd=>{if(m.finished)throw Error('Reabre el análisis antes de cambiar los tiempos.');const next=structuredClone(m);next.periods=next.periods.map((p,i)=>({start:parseTime(fd.get('start'+i)),end:parseTime(fd.get('end'+i))}));next.events.forEach(e=>{if(e.halftime)e.time=next.periods[1].start;});replay(next);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=next);resetEvent(next);closeModal();shell();toast('Tiempos actualizados');});}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return blob;}
function exportModal(email=false,scope='all'){modal(email?'Exportar por correo':'Exportar copia',`<div class="form-stack"><label>Qué quieres exportar<select id="export-scope"><option value="all" ${scope==='all'?'selected':''}>Todos los equipos</option><option value="team" ${scope==='team'?'selected':''}>Un equipo</option><option value="match" ${scope==='match'?'selected':''}>Un partido</option></select></label><label>Equipo<select id="export-team">${db.teams.map(t=>`<option value="${t.id}" ${t.id===teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Partido<select id="export-match">${db.matches.map(m=>`<option value="${m.id}" ${m.id===matchId?'selected':''}>${esc(team(m.teamId)?.name)} vs ${esc(m.opponent)} · ${esc(m.date)}</option>`).join('')}</select></label><p class="hint">La copia contiene los jugadores y los datos necesarios del ámbito elegido. Al importarla se sustituirá ese ámbito.</p>${email?'<div class="notice">Se descargará el archivo y se abrirá tu aplicación de correo. Adjunta el archivo descargado antes de enviarlo.</div>':''}<div class="actions">${button(icon('download')+(email?' Descargar y abrir correo':' Descargar JSON'),'do-export','primary',`data-email="${email?'yes':'no'}"`)}${button('Compartir archivo','share-export')}</div></div>`);}
function exportPacket(){const scope=$('#export-scope').value,id=scope==='team'?$('#export-team').value:scope==='match'?$('#export-match').value:null;if(scope!=='all'&&!id)throw Error('No hay datos disponibles para este ámbito.');return backup(db,scope,id);}
function reportExport(){modal('Exportar informe',`<div class="export-options">${button(icon('file')+' PDF móvil 9:16','mobile-pdf')}${button(icon('file')+' Imágenes 9:16 (ZIP)','mobile-images')}${button(icon('file')+' Imagen continua (PNG)','image-report')}${button(icon('file')+' Imprimir en A4 vertical','print-report')}${button(icon('download')+' CSV para Excel','csv-report')}${button(icon('file')+' Copiar resumen','copy-report')}${button(icon('download')+' Copia JSON del partido','export-match')}</div><p class="hint space-top">El PDF móvil se descarga directamente en páginas 9:16. Las imágenes mantienen la misma proporción y se descargan juntas en ZIP. La impresión A4 es una opción independiente.</p>`);}
function reportText(m){const r=replay(m);return`${reportName(m,team(m.teamId)?.name)}\n${detailLabel(m)}\n${m.date} · ${mins(r.duration)} minutos\n\n`+orderedRows(m,r).map(p=>`${p.number||'—'} ${p.name}: ${p.parts.map(mins).join(' + ')} min · Total ${mins(p.total)} min · ${p.percent}%`).join('\n')+'\n\n'+activityRows(m).map(e=>e.title+' · '+e.time+'\n'+e.text).join('\n\n');}
function csvReport(){const m=currentMatch(),r=replay(m);const cell=v=>{let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};let rows=[['Dorsal','Jugador',...m.periods.map((_,i)=>`Min_${i+1}a`),'Total_min','Porcentaje','Total_segundos','Competicion','Jornada','Ubicacion','Goles_equipo','Goles_rival','Formacion_inicial','Formaciones_posiciones_arbitro'],...orderedRows(m,r).map(p=>[p.number,p.name,...p.parts.map(mins),mins(p.total),p.percent,p.total,m.competition==='league'?'Liga':m.competition==='friendly'?'Amistoso':'',m.round||'',m.venue==='home'?'Casa':m.venue==='away'?'Fuera':'',m.score?.for??'',m.score?.against??'',m.initialFormation?formationLabel(m.initialFormation):'',activityRows(m).map(e=>e.title+' · '+e.time+' · '+e.text).join(' | ')])];download(fileName(m,team(m.teamId)?.name)+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function importFile(file){const reader=new FileReader();reader.onload=()=>{try{const packet=JSON.parse(reader.result);const next=importBackup(db,packet);const date=new Date(packet.exportedAt);if(Number.isNaN(date.getTime()))throw Error('La copia no tiene una fecha válida.');confirmAction('Importar copia',`Copia del <strong>${esc(date.toLocaleString('es'))}</strong>.<br>Ámbito: <strong>${esc({all:'todos los equipos',team:'un equipo',match:'un partido'}[packet.scope])}</strong>.<br><br>Se sustituirán los datos de ese ámbito. Los datos de los jugadores compartidos se actualizarán. Se guardará una copia local de recuperación antes de importar.`,()=>{localStorage.setItem('controlmin.recovery',JSON.stringify(backup(db,'all')));storageError='';commit(next);teamId=db.teams[0]?.id;matchId=null;profileId=null;view='matches';toast('Copia importada');},'Sustituir con esta copia');}catch(e){toast(e.message);}};reader.onerror=()=>toast('No se pudo leer el archivo.');reader.readAsText(file);}
function loadDemo(){const names=['Hugo M.','Lucas R.','Mateo G.','Leo S.','Martín P.','Pablo D.','Dani L.','Álex C.','Bruno V.','Nico A.','Iker T.','Mario F.'];const nums=[1,3,4,6,7,9,11,12,14,15,16,18];const ps=names.map((name,i)=>({id:uid(),name,position:i===0||i===11?'Portero':i<4?'Defensa':i<8?'Centrocampista':'Delantero'}));const tid=uid(),tid2=uid(),mid=uid();const roster=ps.map((p,i)=>({id:p.id,name:p.name,number:String(nums[i])}));const event=(time,out,ins,period=0,halftime=false)=>({id:uid(),type:'sub',time,period,halftime,out:out.map(i=>ps[i].id),in:ins.map(i=>ps[i].id),order:time});const m={id:mid,teamId:tid,opponent:'UD Central',date:'2026-11-15',format:7,competition:'league',round:8,venue:'home',score:{for:2,against:1},initialFormation:'2-3-1',initialPositions:ps.slice(0,7).map(p=>p.id),roster,starters:ps.slice(0,7).map(p=>p.id),periods:[{start:200,end:1700},{start:2300,end:3800}],finished:false,events:[event(800,[6],[7]),event(1100,[4],[9]),event(2300,[2,5,9],[8,10,4],1,true),event(2900,[1],[5],1),event(3200,[4],[6],1),event(3500,[8],[9],1)]};replay(m);const next={version:1,demo:true,players:ps,teams:[{id:tid,name:'CD Norte',category:'Alevín A',format:7,members:ps.map((p,i)=>({playerId:p.id,number:String(nums[i])}))},{id:tid2,name:'Escuela Norte',category:'Grupo de tecnificación',format:7,members:ps.slice(0,9).map((p,i)=>({playerId:p.id,number:String(i+10)}))}],matches:[m]};commit(next);teamId=tid;matchId=mid;view='matches';resetEvent(m);eventTime='18:20';shell();}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 try{switch(a){
 case'nav':view=b.dataset.view;profileId=null;search='';matchId=null;draft=null;shell();break;
 case'new-team':teamModal();break;case'edit-team':teamModal(true);break;
 case'new-player':playerModal();break;case'edit-player':playerModal(id);break;
 case'remove-member':confirmAction('Quitar de este equipo',`¿Quitar a <strong>${esc(pname(id))}</strong> de la plantilla? Su ficha y sus partidos anteriores se conservan.`,()=>mutate(d=>d.teams.find(t=>t.id===teamId).members=d.teams.find(t=>t.id===teamId).members.filter(m=>m.playerId!==id)));break;
 case'profile':profileId=id;playerFilter='';shell();break;
 case'prepare':startDraft();break;
 case'open-match':matchId=id;teamId=currentMatch().teamId;profileId=null;view='matches';resetEvent();shell();break;
 case'open-report':matchId=id;teamId=currentMatch().teamId;profileId=null;view='reports';shell();break;
 case'event-type':tacticSwaps=[];eventType=b.dataset.type;selIn.clear();selOut.clear();tacticPositions=null;tacticFormation=null;tacticFirst=null;if(eventType!=='sub')isHalftime=false;shell();break;
 case'tactic-slot':selectTacticSlot(Number(b.dataset.slot));break;
 case'setup-slot':selectSetupSlot(Number(b.dataset.slot));break;
 case'select-player':{const m=currentMatch();if(m.finished)break;if(b.dataset.side==='in'){if(isTactic())throw Error('Para cambiar posiciones, pulsa los jugadores en el campo.');if(!['sub','referee'].includes(eventType))throw Error('Expulsión y lesión sin cambio no admiten un sustituto.');if(selIn.has(id))selIn.delete(id);else selIn.add(id);}else{if(selOut.has(id))selOut.delete(id);else{if(!['sub','referee'].includes(eventType))selOut.clear();selOut.add(id);}}shell();break;}
 case'halftime':if(currentMatch().finished)throw Error('Reabre el análisis para modificarlo.');resetEvent();eventPeriod=1;eventTime=clock(currentMatch().periods[1].start);isHalftime=true;shell();break;
 case'clear-event':resetEvent();shell();break;
 case'save-event':saveEvent();break;
 case'edit-times':editTimes();break;
 case'finish':{const m=currentMatch();confirmAction(m.finished?'Reabrir análisis':'Finalizar partido',m.finished?'Podrás corregir los eventos y los tiempos. El partido dejará de contar en los acumulados hasta que lo finalices otra vez.':'Comprueba que los tiempos de fin incluyen el añadido y que has registrado todos los cambios. El informe y el historial del jugador usarán estos datos.',()=>{mutate(d=>d.matches.find(x=>x.id===m.id).finished=!m.finished);if(!m.finished)view='reports';resetEvent();});break;}
 case'edit-event':{const e=currentMatch().events.find(x=>x.id===id);editingEvent=id;eventType=e.reason==='referee'?'referee':e.type;tacticSwaps=e.type==='position'?structuredClone(e.swaps||[e.swap]):[];tacticFirst=null;tacticFormation=e.formation||null;tacticPositions=e.type==='formation'?structuredClone(e.positions):null;eventPeriod=e.period;eventTime=clock(e.time);isHalftime=!!e.halftime;selIn=new Set(e.in);selOut=new Set(e.out);shell();window.scrollTo({top:0,behavior:'smooth'});break;}
 case'delete-event':confirmAction('Borrar evento','Los minutos se recalcularán. Si otro evento depende de este cambio, se avisará antes de guardar.',()=>{const m=structuredClone(currentMatch());m.events=m.events.filter(e=>e.id!==id);replay(m);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=m);resetEvent(m);});break;
 case'close-modal':closeModal();break;
 case'export-modal':exportModal();break;case'email-modal':exportModal(true);break;case'export-team':exportModal(false,'team');break;case'export-match':exportModal(false,'match');break;
 case'do-export':{const packet=exportPacket(),name=`timecontrol-${packet.scope}-${new Date().toISOString().slice(0,10)}.json`;download(name,JSON.stringify(packet,null,2));if(b.dataset.email==='yes')window.location.href='mailto:?subject='+encodeURIComponent('Copia de TimeControl')+'&body='+encodeURIComponent('Adjunto mi copia de TimeControl.\n\nRecuerda adjuntar el archivo '+name+' que se acaba de descargar.');toast('Copia descargada'+(b.dataset.email==='yes'?'. Adjunta el archivo en tu correo.':''));break;}
 case'share-export':{const packet=exportPacket(),file=new File([JSON.stringify(packet,null,2)],'timecontrol-copia.json',{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Copia de TimeControl'});}catch(e){if(e.name!=='AbortError')throw e;}}else toast('Este navegador no comparte archivos. Descarga la copia y adjúntala en tu correo.');break;}
 case'import':$('#import-file').value='';$('#import-file').click();break;
 case'recovery':{const raw=localStorage.getItem('controlmin.recovery');if(!raw)throw Error('Todavía no hay una copia previa a una importación.');download('timecontrol-recuperacion.json',raw);break;}
 case'report-export':reportExport();break;
 case'print-report':closeModal();printReport();break;
 case'edit-match':editMatchDetails();break;
 case'mobile-pdf':case'mobile-images':case'mobile-totals':{const totals=a==='mobile-totals',m=totals?null:currentMatch(),r=m?replay(m):null;const report=mobileReportPages({match:m,teamName:m?team(m.teamId)?.name:'',rows:m?orderedRows(m,r):orderedTotals(),duration:r?.duration,demo:db.demo});const out=a==='mobile-images'?await mobilePNGs(report):await mobilePDF(report);download(out.name,out.blob,out.blob.type);toast('Informe 9:16 descargado');break;}
 case'image-report':case'image-players':{const totals=a==='image-players',m=totals?null:currentMatch(),r=m?replay(m):null;const out=await reportImage({match:m,teamName:m?team(m.teamId)?.name:'',rows:m?orderedRows(m,r):orderedTotals(),duration:r?.duration,demo:db.demo});download(out.name,out.blob,'image/png');toast('Imagen vertical descargada');break;}
 case'sort-report':{const m=currentMatch(),old=m.reportSort||{key:'number',direction:'asc'};mutate(d=>d.matches.find(x=>x.id===m.id).reportSort={key:b.dataset.key,direction:old.key===b.dataset.key&&old.direction==='asc'?'desc':'asc'});shell();break;}
 case'sort-players':{const old=db.preferences?.playersSort||{key:'name',direction:'asc'};mutate(d=>{d.preferences||={};d.preferences.playersSort={key:b.dataset.key,direction:old.key===b.dataset.key&&old.direction==='asc'?'desc':'asc'};});shell();break;}
 case'csv-players':exportPlayerTotals();break;
 case'print-players':printReport(true);break;
 case'csv-report':csvReport();toast('CSV descargado');break;
 case'copy-report':await navigator.clipboard.writeText(reportText(currentMatch()));toast('Resumen copiado');break;
 case'demo':loadDemo();break;
 case'clear-demo':case'reset':confirmAction('Empezar de nuevo','Se borrarán todos los equipos, jugadores y partidos de este navegador. Exporta antes una copia si quieres conservarlos.',()=>{storageError='';commit(emptyDB());teamId=null;matchId=null;profileId=null;view='matches';});break;
 }
 }catch(e){toast(e.message);}
});
document.addEventListener('change',ev=>{const el=ev.target;try{
 if(el.id==='tactic-formation'){tacticFormation=normalizeFormation(currentMatch().format,el.value);tacticFirst=null;shell();}
 if(el.id==='team-select'){teamId=el.value;matchId=null;profileId=null;draft=null;view='matches';shell();}
 if(el.id==='event-period'){eventPeriod=+el.value;eventTime=clock(currentMatch().periods[eventPeriod].start);selIn.clear();selOut.clear();tacticPositions=null;tacticSwaps=[];tacticFirst=null;isHalftime=false;shell();}
 if(el.id==='event-time'){eventTime=el.value;const time=parseTime(eventTime),m=currentMatch();const found=m.periods.findIndex(p=>time>=p.start&&time<=p.end);if(found>=0)eventPeriod=found;else throw Error('El tiempo debe estar dentro de una parte. Para cambios de descanso usa su botón.');selIn.clear();selOut.clear();if(isTactic()){const st=selectedState(m);if(eventType==='formation')tacticPositions=fitPositions(tacticPositions||st.positions,st.field,m.format);else{if(tacticSwaps.some(pair=>pair.some(id=>!st.field.includes(id)))){tacticSwaps=[];toast('La alineación en ese instante es distinta. Revisa los puestos.');}tacticPositions=null;}}else{tacticPositions=null;tacticSwaps=[];}tacticFirst=null;isHalftime=false;shell();}
 if(el.id==='profile-team'){playerFilter=el.value;shell();}
 if(el.id==='existing-player'){const name=$('#new-player-name');name.disabled=!!el.value;name.required=!el.value;}
 if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>10*1024*1024)throw Error('La copia es demasiado grande (máximo 10 MB).');importFile(el.files[0]);}
 if(el.dataset.draft){syncDraft();const p=draft.roster.find(p=>p.id===el.dataset.id);const key=el.dataset.draft;p[key]=key==='number'?el.value:el.checked;if(key==='called'&&!p.called)p.starter=false;if(key!=='number')shell();}
 if(el.closest('#setup-form')&&['periodCount','format','competition','initialFormation'].includes(el.name)){syncDraft();if(el.name==='format'){draft.initialFormation=defaultFormation(draft.format);draft.initialPositions=[];}shell();}
 }catch(e){toast(e.message);}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='event-time')eventTime=el.value;if(['roster-search','player-search'].includes(el.id)){const pos=el.selectionStart;search=el.value;renderContent();const n=$('#'+el.id);n.focus();n.setSelectionRange(pos,pos);}});
function syncDraft(){const f=$('#setup-form');if(!f||!draft)return;draft.opponent=f.elements.opponent.value;draft.initialFormation=f.elements.initialFormation.value;draft.competition=f.elements.competition.value;draft.round=f.elements.round?.value||'';draft.venue=f.elements.venue.value;draft.goalsFor=f.elements.goalsFor.value;draft.goalsAgainst=f.elements.goalsAgainst.value;draft.score=(f.elements.goalsFor.value!==''&&f.elements.goalsAgainst.value!=='')?{for:+f.elements.goalsFor.value,against:+f.elements.goalsAgainst.value}:null;draft.date=f.elements.date.value;draft.format=+f.elements.format.value;draft.periodCount=+f.elements.periodCount.value;for(let i=0;i<2;i++){if(f.elements['start'+i])draft.periods[i]={start:f.elements['start'+i].value,end:f.elements['end'+i].value};}}
document.addEventListener('submit',ev=>{if(ev.target.id!=='setup-form')return;ev.preventDefault();try{syncDraft();const m={id:draft.id,teamId:draft.teamId,opponent:draft.opponent.trim(),date:draft.date,format:draft.format,initialFormation:normalizeFormation(draft.format,draft.initialFormation),initialPositions:fitPositions(draft.initialPositions,draft.roster.filter(p=>p.called&&p.starter).map(p=>p.id),draft.format),...readDetails(new FormData(ev.target)),periods:draft.periods.slice(0,draft.periodCount).map(p=>({start:parseTime(p.start),end:parseTime(p.end)})),roster:draft.roster.filter(p=>p.called).map(({id,name,number})=>({id,name,number})),starters:draft.roster.filter(p=>p.called&&p.starter).map(p=>p.id),events:[],finished:false};if(!m.date)throw Error('Selecciona una fecha.');replay(m);mutate(d=>d.matches.push(m));matchId=m.id;view='matches';draft=null;resetEvent(m);shell();toast('Partido preparado');}catch(e){$('#setup-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}});
window.addEventListener('storage',ev=>{if(ev.key==='controlmin.v1'){storageError='Los datos han cambiado en otra pestaña. Recarga esta página antes de guardar para evitar sobrescribirlos.';shell();}});
installClocks();
shell();

if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function matchDetailFields(m){return `<label>Tipo de partido<select name="competition" required><option value="" ${!m.competition?'selected':''}>Selecciona</option><option value="league" ${m.competition==='league'?'selected':''}>Liga</option><option value="friendly" ${m.competition==='friendly'?'selected':''}>Amistoso</option></select></label>${m.competition==='friendly'?'':`<label>Jornada de liga<input name="round" type="number" min="1" max="999" step="1" value="${esc(m.round??'')}" ${m.competition==='league'?'required':''} placeholder="Ej. 8"></label>`}<label>Localización<select name="venue" required><option value="" ${!m.venue?'selected':''}>Selecciona</option><option value="home" ${m.venue==='home'?'selected':''}>En casa</option><option value="away" ${m.venue==='away'?'selected':''}>Fuera de casa</option></select></label><label>Goles de tu equipo<input name="goalsFor" type="number" min="0" max="99" step="1" value="${esc(m.goalsFor??m.score?.for??'')}" placeholder="Sin resultado"></label><label>Goles del rival<input name="goalsAgainst" type="number" min="0" max="99" step="1" value="${esc(m.goalsAgainst??m.score?.against??'')}" placeholder="Sin resultado"></label>`;}
function readDetails(fd){const competition=fd.get('competition'),round=competition==='league'?Number(fd.get('round')):null,venue=fd.get('venue'),a=fd.get('goalsFor'),b=fd.get('goalsAgainst');if(!['league','friendly'].includes(competition))throw Error('Selecciona Liga o Amistoso.');if(competition==='league'&&(!round||!Number.isInteger(round)))throw Error('Introduce el número de jornada de liga.');if((a==='')!==(b===''))throw Error('Completa los dos goles del resultado o deja ambos vacíos.');return{competition,round,venue,score:a===''?null:{for:Number(a),against:Number(b)}};}
function scoreline(m){const f=fixture(m,team(m.teamId)?.name);return `${esc(f.home)} <strong class="match-score">${m.score?f.homeGoals+' – '+f.awayGoals:'vs'}</strong> ${esc(f.away)}`;}
function editMatchDetails(){const m=currentMatch();modal('Datos del partido',`<div class="fields"><label>Rival<input name="opponent" value="${esc(m.opponent)}" required maxlength="80"></label><label>Fecha<input name="date" type="date" value="${esc(m.date)}" required></label>${matchDetailFields(m)}</div><p class="hint space-top">El resultado se introduce desde la perspectiva de tu equipo. En el informe se mostrará primero el equipo local.</p>`,fd=>{const next={...structuredClone(m),opponent:fd.get('opponent').trim(),date:fd.get('date'),...readDetails(fd)};replay(next);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=next);closeModal();shell();toast('Datos del partido actualizados');});const select=$('#modal [name="competition"]');select.addEventListener('change',()=>{const input=$('#modal [name="round"]');if(input){input.disabled=select.value==='friendly';input.required=select.value==='league';}else if(select.value==='league'){const label=document.createElement('label');label.innerHTML='Jornada de liga<input name="round" type="number" min="1" max="999" step="1" required>';select.parentElement.after(label);}});}
function orderedRows(m,r){return sortRows(r.rows,m.reportSort||{key:'number',direction:'asc'});}
function sortHeader(label,key,sort,action='sort-report',extra=''){const active=sort?.key===key,dir=active?(sort.direction==='desc'?'descending':'ascending'):'none';return `<th aria-sort="${dir}"><button class="sort-heading" data-action="${action}" data-key="${key}" title="Ordenar por ${label}">${label}<span aria-hidden="true">${active?(sort.direction==='desc'?' ↓':' ↑'):' ↕'}</span></button>${extra}</th>`;}
function bar(m,row,i){const p=m.periods[i];return `<div class="track">${row.intervals.filter(iv=>iv.period===i).map(iv=>`<span class="segment" style="left:${(iv.start-p.start)/(p.end-p.start)*100}%;width:${(iv.end-iv.start)/(p.end-p.start)*100}%" title="Cámara ${clock(iv.start)}–${clock(iv.end)}"></span>`).join('')}<span class="track-label ${row.parts[i]?'':'track-zero'}">${mins(row.parts[i])} min</span></div>`;}
function timeline(m,r){const sort=m.reportSort||{key:'number',direction:'asc'},rows=orderedRows(m,r);return `<div class="table-wrap screen-table"><table class="timeline-table"><colgroup><col class="dorsal-col"><col class="player-col">${m.periods.map(()=>'<col>').join('')}<col class="total-col"><col class="pct-col"></colgroup><thead><tr>${sortHeader('N.º','number',sort)}${sortHeader('Jugador','name',sort)}${m.periods.map((p,i)=>sortHeader((i+1)+'.ª parte','part'+i,sort,'sort-report',`<div class="timeline-head"><span>0′</span><span>${clock(p.end-p.start)}</span></div>`)).join('')}${sortHeader('Total','total',sort)}${sortHeader('%','percent',sort)}</tr></thead><tbody>${rows.map(row=>`<tr><td><span class="num-chip">${esc(row.number||'—')}</span></td><td class="person"><strong>${esc(row.name)}</strong></td>${m.periods.map((p,i)=>`<td>${bar(m,row,i)}</td>`).join('')}<td><strong>${mins(row.total)} min</strong></td><td class="muted">${row.percent}%</td></tr>`).join('')}</tbody></table></div><div class="print-roster">${rows.map(row=>`<article class="print-player"><div class="print-player-name"><strong><span class="num-chip">${esc(row.number||'—')}</span> ${esc(row.name)}</strong><span><b>${mins(row.total)} min</b> · ${row.percent}%</span></div><div class="print-parts">${m.periods.map((p,i)=>`<div><span class="print-half">${i+1}.ª parte · ${clock(p.end-p.start)}</span>${bar(m,row,i)}</div>`).join('')}</div></article>`).join('')}</div><div class="legend"><span><i></i>En el campo</span><span><i class="off"></i>Fuera del campo</span><span>Descanso excluido</span></div>`;}
function playerTotals(){return db.players.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=>{const rs=db.matches.filter(m=>m.finished&&m.roster.some(r=>r.id===p.id)).map(m=>replay(m).rows.find(r=>r.id===p.id));return{...p,teams:db.teams.filter(t=>t.members.some(m=>m.playerId===p.id)||db.matches.some(m=>m.teamId===t.id&&m.roster.some(r=>r.id===p.id))).map(t=>t.name).join(', ')||'Sin equipo',appearances:rs.length,total:rs.reduce((s,r)=>s+r.total,0)};});}
function orderedTotals(){return sortRows(playerTotals(),db.preferences?.playersSort||{key:'name',direction:'asc'});}
function players(){const sort=db.preferences?.playersSort||{key:'name',direction:'asc'},rows=orderedTotals();return head('Jugadores','Una ficha única, con su historial en todos los equipos.',button(icon('file')+' Imagen continua','image-players')+button(icon('download')+' CSV','csv-players')+button(icon('file')+' PDF móvil 9:16','mobile-totals')+button('Imprimir','print-players','quiet'),'Historial de participación')+`<section class="card"><div class="card-head"><h2>Total de minutos <span class="badge green">${rows.length}</span></h2><input id="player-search" class="search no-print" placeholder="Buscar jugador" value="${esc(search)}" aria-label="Buscar jugador"></div><div class="table-wrap totals-table"><table><thead><tr>${sortHeader('Jugador','name',sort,'sort-players')}${sortHeader('Equipos','teams',sort,'sort-players')}${sortHeader('Partidos','appearances',sort,'sort-players')}${sortHeader('Minutos','total',sort,'sort-players')}<th class="no-print"></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="namecell">${avatar(p.name)}<strong>${esc(p.name)}</strong></div></td><td class="muted small">${esc(p.teams)}</td><td>${p.appearances}</td><td><strong>${mins(p.total)} min</strong></td><td class="no-print">${button('Ver ficha '+icon('arrow'),'profile','quiet','data-id="'+p.id+'"')}</td></tr>`).join('')}</tbody></table></div><div class="note">Pulsa las columnas para ordenar. El PDF y el CSV mantienen este orden y el filtro de búsqueda. Los acumulados incluyen solo partidos finalizados y usan los segundos reales.</div></section>`;}
function csvCell(v){let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportPlayerTotals(){const rows=[['Jugador','Equipos','Partidos','Minutos','Segundos'],...orderedTotals().map(p=>[p.name,p.teams,p.appearances,mins(p.total),p.total])];download('TimeControl-total-de-minutos.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function printReport(totals=false){const title=document.title;document.title=totals?'TimeControl - Total de minutos':reportName(currentMatch(),team(currentMatch().teamId)?.name);const restore=()=>{document.title=title;};window.addEventListener('afterprint',restore,{once:true});try{window.print();}catch(e){restore();throw e;}}
function isTactic(){return ['formation','position'].includes(eventType);}
function pitchMarkup(format,formation,positions,players,action,first=null,disabled=false){const slots=formationSlots(format,formation),byId=new Map(players.map(p=>[p.id,p]));return `<div class="pitch formation-pitch"><svg class="pitch-lines" viewBox="0 0 500 650" preserveAspectRatio="none" aria-hidden="true"><rect x="16" y="16" width="468" height="618" rx="4"/><path d="M16 325h468M150 16v95h200V16M207 16v37h86V16M150 634v-95h200v95M207 634v-37h86v37"/><circle cx="250" cy="325" r="57"/></svg><span class="pitch-direction">↑ Ataque</span>${slots.map(slot=>{const p=byId.get(positions[slot.index]),selected=first===slot.index;return `<button type="button" class="formation-player ${selected||(action==='select-player'&&selOut.has(p?.id))?'picked':''} ${!p?'vacant':''}" style="left:${slot.x}%;top:${slot.y}%;width:${Math.min(24,100/(Math.max(...normalizeFormation(format,formation).split('-').map(Number))+1)-1)}%" data-action="${action}" data-slot="${slot.index}" ${p?`data-id="${p.id}"`:''} data-side="out" aria-label="${esc(slot.label+': '+(p?p.name:'Vacante'))}" ${disabled?'disabled':''}>${p?`<span class="shirt-number">${esc(p.number||'—')}</span><strong>${esc(p.name)}</strong>`:'<span class="shirt-number">·</span><strong>Vacante</strong>'}<small>${esc(slot.label)}</small></button>`;}).join('')}</div>`;}
function setupFormationPitch(){try{const formation=normalizeFormation(draft.format,draft.initialFormation),ids=draft.roster.filter(p=>p.called&&p.starter).map(p=>p.id);draft.initialPositions=fitPositions(draft.initialPositions,ids,draft.format);return `<section class="setup-tactics space-top"><div class="card-head"><h2>Formación inicial · ${esc(formationLabel(formation))}</h2></div><p class="hint">Selecciona los titulares y pulsa dos puestos para intercambiarlos. El portero va abajo.</p>${pitchMarkup(draft.format,formation,draft.initialPositions,draft.roster,'setup-slot',setupFirst)}</section>`;}catch(e){return `<p class="error">${esc(e.message)}</p>`;}}
function selectSetupSlot(slot){if(setupFirst===null){setupFirst=slot;}else{[draft.initialPositions[setupFirst],draft.initialPositions[slot]]=[draft.initialPositions[slot],draft.initialPositions[setupFirst]];setupFirst=null;}syncDraft();shell();}
function tacticalState(m,state){const formation=isTactic()?(tacticFormation||state.formation):state.formation;if(isTactic()&&!tacticPositions){tacticPositions=[...(state.positions||fitPositions([],state.field,m.format))];if(eventType==='position')for(const pair of tacticSwaps){const a=tacticPositions.indexOf(pair[0]),b=tacticPositions.indexOf(pair[1]);if(a>=0&&b>=0)[tacticPositions[a],tacticPositions[b]]=[tacticPositions[b],tacticPositions[a]];}}return{formation:formation||defaultFormation(m.format),positions:isTactic()?tacticPositions:(state.positions||fitPositions([],state.field,m.format))};}
function matchPitch(m,state){try{const t=tacticalState(m,state);return `<div class="formation-caption"><span class="badge green">${esc(formationLabel(t.formation))}</span><span class="hint">${isTactic()?'Pulsa dos puestos para intercambiar':'El cambio entrante ocupa el puesto del saliente'}</span></div>${pitchMarkup(m.format,t.formation,t.positions,m.roster,isTactic()?'tactic-slot':'select-player',isTactic()?tacticFirst:null,m.finished)}${isTactic()?'<p class="hint space-top">La vista es una propuesta hasta confirmar el evento.</p>':''}`;}catch(e){return `<p class="error">${esc(e.message)}</p>`;}}
function tacticControls(m,state){const f=tacticFormation||state.formation||defaultFormation(m.format);return `<div class="tactic-controls">${eventType==='formation'?`<label>Nueva formación (sin portero)<input id="tactic-formation" list="tactic-presets" value="${esc(f)}" placeholder="2-3-1"><datalist id="tactic-presets">${formationPresets[m.format].map(v=>`<option value="${v}">${formationLabel(v)}</option>`).join('')}</datalist></label>`:''}<p class="tactic-explainer">${eventType==='position'?'Pulsa dos jugadores del campo para intercambiar posiciones. Puedes repetir antes de confirmar.':'Elige el sistema y pulsa dos puestos en el campo para ajustar la distribución.'} El evento se guardará en el tiempo de cámara indicado.</p>${eventType==='position'?`<span class="badge green">${tacticSwaps.length} intercambios preparados</span>`:''}</div>`;}
function selectTacticSlot(slot){if(currentMatch().finished)return;const state=selectedState(currentMatch()),t=tacticalState(currentMatch(),state);if(tacticFirst===null){tacticFirst=slot;}else{const a=t.positions[tacticFirst],b=t.positions[slot];if(eventType==='position'&&(!a||!b||a===b)){tacticFirst=null;throw Error('Selecciona dos jugadores distintos que estén en el campo.');}if(tacticFirst!==slot){[tacticPositions[tacticFirst],tacticPositions[slot]]=[tacticPositions[slot],tacticPositions[tacticFirst]];if(eventType==='position')tacticSwaps.push([a,b]);}tacticFirst=null;}shell();}
function saveEvent(){const m=currentMatch();if(m.finished)throw Error('Reabre el análisis para registrar cambios.');const time=isHalftime?m.periods[1].start:parseTime(eventTime||clock(m.periods[eventPeriod].start)),old=m.events.find(e=>e.id===editingEvent);let e={id:editingEvent||uid(),order:old?.order??Math.max(0,...m.events.map(e=>e.order||0))+1,type:eventType==='referee'?'sub':eventType,period:eventPeriod,time,halftime:isHalftime};if(eventType==='formation'){const state=selectedState(m),t=tacticalState(m,state);Object.assign(e,{formation:normalizeFormation(m.format,tacticFormation||t.formation),positions:[...t.positions]});}else if(eventType==='position'){if(!tacticSwaps.length)throw Error('Pulsa dos jugadores del campo para preparar un intercambio.');e.swaps=structuredClone(tacticSwaps);}else Object.assign(e,{in:['sub','referee'].includes(eventType)?[...selIn]:[],out:[...selOut],...(eventType==='referee'?{reason:'referee'}:{})});const next=structuredClone(m);next.events=next.events.filter(v=>v.id!==e.id).concat(e);replay(next);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=next);const keepTime=clock(time),keepPeriod=eventPeriod;resetEvent();eventTime=keepTime;eventPeriod=keepPeriod;shell();toast('Evento guardado. Campo y minutos actualizados.');}
function eventList(m,events){return events.length?events.map(e=>{const names=ids=>(ids||[]).map(id=>esc(m.roster.find(p=>p.id===id)?.name||'Jugador')).join(', ');let content;if(e.type==='formation')content='<strong>Cambio de formación · '+esc(formationLabel(e.formation))+'</strong>';else if(e.type==='position')content='<strong>Intercambio de posiciones</strong><br>'+(e.swaps||[e.swap]).map(pair=>names(pair)).join(' / ');else content=(e.type==='sub'?'<span style="color:var(--green)">↑ '+names(e.in)+'</span><br>':'')+'↓ '+names(e.out)+'<small>'+(e.reason==='referee'?'Petición del árbitro · Puede volver a entrar':e.type==='red'?'Expulsión':e.type==='injury'?'Lesión sin cambio':(e.period+1)+'.ª parte')+'</small>';return `<div class="event-item"><span class="badge ${e.halftime?'green':''}">${e.halftime?'Descanso':clock(e.time)}</span><div class="content">${content}</div>${!m.finished?`<button class="iconbtn" data-action="edit-event" data-id="${e.id}" aria-label="Editar evento ${clock(e.time)}">${icon('edit')}</button><button class="iconbtn" data-action="delete-event" data-id="${e.id}" aria-label="Borrar evento ${clock(e.time)}">${icon('trash')}</button>`:''}</div>`;}).join(''):'<p class="hint">Los cambios y modificaciones tácticas aparecerán aquí.</p>';}
function tacticalReport(m){const rows=activityRows(m);return rows.length?`<section class="card space-top tactical-report"><div class="card-head"><h2>Formaciones, posiciones y árbitro</h2></div>${rows.map(e=>`<article class="activity-row"><strong>${esc(e.title)}</strong><small>${esc(e.time)}</small><p>${esc(e.text)}</p></article>`).join('')}</section>`:'';}
